const securityHeaders={
  'Strict-Transport-Security':'max-age=31536000; includeSubDomains; preload',
  'X-Content-Type-Options':'nosniff',
  'X-Frame-Options':'SAMEORIGIN',
  'Referrer-Policy':'strict-origin-when-cross-origin',
  'Permissions-Policy':'camera=(), microphone=(), geolocation=()'
};
const jsonHeaders={...securityHeaders,'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Matrix-Origin':'cloudflare-worker-email-lifecycle'};
const emailRoutes=new Set([
  '/newsletter-signup','/subscribe-newsletter','/api/membership/signup',
  '/api/email/verify','/api/email/preferences','/api/email/unsubscribe','/api/email/resubscribe',
  '/api/email/subscriber','/api/email/provider-webhook','/api/email/admin/health',
  '/api/email/admin/campaigns','/api/email/admin/process-outbox','/api/email/admin/run-automation'
]);
const segmentDefinitions={
  public_daily_brief:{id:'segment-public-daily',label:'Public Daily Brief',minimumTier:'public',preference:'public_daily_brief',marketing:true},
  public_weekly_digest:{id:'segment-public-weekly',label:'Public Weekly Digest',minimumTier:'public',preference:'public_weekly_digest',marketing:true},
  registered_release_notices:{id:'segment-registered-release',label:'Registered Release Notices',minimumTier:'registered',preference:'release_notices',marketing:true},
  supporter_weekly_member_brief:{id:'segment-supporter-weekly',label:'Supporter Weekly Member Brief',minimumTier:'supporter_3',preference:'supporter_weekly_member_brief',marketing:true},
  intelligence_daily_member_brief:{id:'segment-intelligence-daily',label:'Intelligence Daily Member Brief',minimumTier:'intelligence_6',preference:'intelligence_daily_member_brief',marketing:true},
  research_pro_reports:{id:'segment-research-reports',label:'Research Pro Reports',minimumTier:'research_pro_9',preference:'research_pro_reports',marketing:true},
  transactional_account:{id:'segment-transactional',label:'Transactional Account Email',minimumTier:'public',preference:null,marketing:false},
  suppressed_do_not_send:{id:'segment-suppressed',label:'Suppressed — Do Not Send',minimumTier:'public',preference:null,marketing:false}
};
const tierRank={public:0,free:0,registered:1,supporter:2,supporter_3:2,intelligence:3,intelligence_6:3,research_pro:4,research_pro_9:4,admin:9};
let schemaPromise;
let deterministicCounter=0;

function clean(value,max=1000){return String(value??'').replace(/<[^>]*>/g,'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max)}
function html(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function json(data,status=200,extra={}){return new Response(JSON.stringify(data,null,2),{status,headers:{...jsonHeaders,...extra}})}
function redirect(location){return new Response(null,{status:303,headers:{...securityHeaders,Location:location,'Cache-Control':'no-store'}})}
function bool(value,fallback=false){if(value===undefined||value===null||value==='')return fallback;return value===true||value===1||['1','true','yes','on'].includes(String(value).trim().toLowerCase())}
function validEmail(value){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value||'').trim())}
function hasD1(env){return Boolean(env?.MEMBERS_DB&&typeof env.MEMBERS_DB.prepare==='function')}
function now(env){const fixed=clean(env?.EMAIL_TEST_NOW||'',80);return fixed&&Number.isFinite(Date.parse(fixed))?new Date(fixed):new Date()}
function iso(env,offsetMs=0){return new Date(now(env).getTime()+offsetMs).toISOString()}
function origin(request){const url=new URL(request.url);return ['matrixreprogrammed.com','www.matrixreprogrammed.com','localhost','127.0.0.1'].includes(url.hostname)?url.origin:'https://matrixreprogrammed.com'}
function secureEqual(a,b){a=String(a||'');b=String(b||'');if(!a||a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0}
function adminAllowed(request,env){return Boolean(env?.ADMIN_API_TOKEN&&secureEqual(request.headers.get('x-admin-token')||'',env.ADMIN_API_TOKEN))}
function testMode(env){return String(env?.EMAIL_TEST_MODE||'').toLowerCase()==='true'}
function automationEnabled(env){return String(env?.EMAIL_AUTOMATION_ENABLED||'').toLowerCase()==='true'}
function providerConfigured(env){return Boolean(env?.BREVO_API_KEY&&env?.MEMBERS_FROM_EMAIL)}
function providerFetch(env){return typeof env?.EMAIL_PROVIDER_FETCH==='function'?env.EMAIL_PROVIDER_FETCH:fetch}
function tierAtLeast(actual,required){return Number(tierRank[String(actual||'free')]??0)>=Number(tierRank[String(required||'public')]??0)}
function randomBytes(length=32){const bytes=new Uint8Array(length);crypto.getRandomValues(bytes);return bytes}
function base64Url(bytes){let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function tokenValue(env,prefix='token'){if(testMode(env)){deterministicCounter+=1;return `${prefix}-test-${deterministicCounter.toString().padStart(4,'0')}`}return base64Url(randomBytes(32))}
function id(env,prefix='email'){if(testMode(env)){deterministicCounter+=1;return `${prefix}-test-${deterministicCounter.toString().padStart(4,'0')}`}return `${prefix}-${crypto.randomUUID()}`}
async function hash(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value||'')));return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
async function body(request){const type=request.headers.get('content-type')||'';if(type.includes('application/json'))return request.json().catch(()=>({}));const form=await request.formData().catch(()=>null);return form?Object.fromEntries(form.entries()):{}}
async function first(statement){try{return await statement.first()}catch{return null}}
async function all(statement){try{const result=await statement.all();return Array.isArray(result?.results)?result.results:[]}catch{return[]}}
async function audit(env,actorId,action,targetType,targetId,metadata={}){if(!hasD1(env))return;await env.MEMBERS_DB.prepare('INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').bind(id(env,'email-audit'),actorId||'email-system',action,targetType,targetId||'',JSON.stringify(metadata),iso(env)).run().catch(()=>null)}

async function ensureSchema(env){
  if(!hasD1(env))throw new Error('MEMBERS_DB D1 binding is unavailable');
  if(schemaPromise)return schemaPromise;
  schemaPromise=(async()=>{
    const statements=[
      `CREATE TABLE IF NOT EXISTS email_preferences (member_id TEXT PRIMARY KEY,public_daily_brief INTEGER NOT NULL DEFAULT 0 CHECK(public_daily_brief IN (0,1)),public_weekly_digest INTEGER NOT NULL DEFAULT 1 CHECK(public_weekly_digest IN (0,1)),release_notices INTEGER NOT NULL DEFAULT 1 CHECK(release_notices IN (0,1)),supporter_weekly_member_brief INTEGER NOT NULL DEFAULT 1 CHECK(supporter_weekly_member_brief IN (0,1)),intelligence_daily_member_brief INTEGER NOT NULL DEFAULT 1 CHECK(intelligence_daily_member_brief IN (0,1)),research_pro_reports INTEGER NOT NULL DEFAULT 1 CHECK(research_pro_reports IN (0,1)),locale TEXT NOT NULL DEFAULT 'en',timezone TEXT NOT NULL DEFAULT 'Europe/Paris',digest_day INTEGER,digest_hour INTEGER,updated_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE)`,
      `CREATE TABLE IF NOT EXISTS email_action_tokens (id TEXT PRIMARY KEY,member_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,purpose TEXT NOT NULL,scope_json TEXT NOT NULL DEFAULT '{}',expires_at TEXT NOT NULL,used_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE)`,
      `CREATE INDEX IF NOT EXISTS idx_email_action_tokens_member_purpose ON email_action_tokens(member_id,purpose,created_at DESC)`,
      `CREATE TABLE IF NOT EXISTS email_provider_contacts (member_id TEXT NOT NULL,provider TEXT NOT NULL DEFAULT 'brevo',provider_contact_id TEXT,sync_status TEXT NOT NULL,provider_state_json TEXT NOT NULL DEFAULT '{}',local_state_hash TEXT NOT NULL,last_synced_at TEXT,last_checked_at TEXT,last_error TEXT,updated_at TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(member_id,provider),FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE)`,
      `CREATE TABLE IF NOT EXISTS email_segments (id TEXT PRIMARY KEY,segment_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,minimum_tier TEXT NOT NULL,marketing INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,rules_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL,created_at TEXT NOT NULL)`,
      `CREATE TABLE IF NOT EXISTS email_segment_memberships (segment_id TEXT NOT NULL,member_id TEXT NOT NULL,state TEXT NOT NULL,source TEXT NOT NULL,reason TEXT,eligible_at TEXT,activated_at TEXT,removed_at TEXT,updated_at TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(segment_id,member_id),FOREIGN KEY(segment_id) REFERENCES email_segments(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE)`,
      `CREATE TABLE IF NOT EXISTS email_campaign_content_versions (id TEXT PRIMARY KEY,campaign_kind TEXT NOT NULL,subject TEXT NOT NULL,preheader TEXT NOT NULL DEFAULT '',html_content TEXT NOT NULL,text_content TEXT NOT NULL,canonical_record_ids_json TEXT NOT NULL DEFAULT '[]',content_hash TEXT NOT NULL UNIQUE,evidence_checkpoint_at TEXT NOT NULL,fact_speculation_boundary_verified INTEGER NOT NULL DEFAULT 0,reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL)`,
      `CREATE TABLE IF NOT EXISTS email_campaigns (id TEXT PRIMARY KEY,campaign_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,segment_id TEXT,content_version_id TEXT NOT NULL,status TEXT NOT NULL,provider TEXT NOT NULL DEFAULT 'brevo',provider_campaign_id TEXT,scheduled_at TEXT,started_at TEXT,completed_at TEXT,recipient_count INTEGER NOT NULL DEFAULT 0,sent_count INTEGER NOT NULL DEFAULT 0,failed_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,updated_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(segment_id) REFERENCES email_segments(id),FOREIGN KEY(content_version_id) REFERENCES email_campaign_content_versions(id))`,
      `CREATE TABLE IF NOT EXISTS email_outbox (id TEXT PRIMARY KEY,member_id TEXT NOT NULL,campaign_id TEXT,message_kind TEXT NOT NULL,recipient_email_hash TEXT NOT NULL,payload_json TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL,attempt_count INTEGER NOT NULL DEFAULT 0,available_at TEXT NOT NULL,locked_at TEXT,provider_message_id TEXT,last_error TEXT,updated_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,FOREIGN KEY(campaign_id) REFERENCES email_campaigns(id) ON DELETE SET NULL)`,
      `CREATE INDEX IF NOT EXISTS idx_email_outbox_ready ON email_outbox(status,available_at)`,
      `CREATE TABLE IF NOT EXISTS email_deliveries (id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL,member_id TEXT,recipient_email_hash TEXT NOT NULL,provider_message_id TEXT,status TEXT NOT NULL,queued_at TEXT NOT NULL,sent_at TEXT,delivered_at TEXT,opened_at TEXT,clicked_at TEXT,failed_at TEXT,last_event_at TEXT,failure_reason TEXT,updated_at TEXT NOT NULL,FOREIGN KEY(campaign_id) REFERENCES email_campaigns(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL)`,
      `CREATE TABLE IF NOT EXISTS email_events (id TEXT PRIMARY KEY,provider TEXT NOT NULL DEFAULT 'brevo',provider_event_id TEXT NOT NULL,provider_message_id TEXT,campaign_id TEXT,member_id TEXT,event_type TEXT NOT NULL,event_at TEXT NOT NULL,payload_hash TEXT NOT NULL,payload_json TEXT NOT NULL,processed_at TEXT,processing_status TEXT NOT NULL,processing_error TEXT,created_at TEXT NOT NULL,UNIQUE(provider,provider_event_id))`,
      `CREATE TABLE IF NOT EXISTS email_suppressions (id TEXT PRIMARY KEY,member_id TEXT,recipient_email_hash TEXT NOT NULL,scope TEXT NOT NULL,segment_key TEXT,reason TEXT NOT NULL,source TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,suppressed_at TEXT NOT NULL,cleared_at TEXT,cleared_by_consent_id TEXT,updated_at TEXT NOT NULL,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL)`,
      `CREATE INDEX IF NOT EXISTS idx_email_suppressions_member ON email_suppressions(member_id,active)`,
      `CREATE TABLE IF NOT EXISTS email_webhook_receipts (id TEXT PRIMARY KEY,provider TEXT NOT NULL DEFAULT 'brevo',request_id TEXT NOT NULL,signature_valid INTEGER NOT NULL,payload_hash TEXT NOT NULL,event_count INTEGER NOT NULL DEFAULT 0,processing_status TEXT NOT NULL,received_at TEXT NOT NULL,processed_at TEXT,last_error TEXT,UNIQUE(provider,request_id))`,
      `CREATE TABLE IF NOT EXISTS email_reconciliation_runs (id TEXT PRIMARY KEY,provider TEXT NOT NULL DEFAULT 'brevo',scope TEXT NOT NULL,status TEXT NOT NULL,local_count INTEGER NOT NULL DEFAULT 0,provider_count INTEGER NOT NULL DEFAULT 0,matched_count INTEGER NOT NULL DEFAULT 0,mismatch_count INTEGER NOT NULL DEFAULT 0,result_json TEXT NOT NULL DEFAULT '{}',started_at TEXT NOT NULL,completed_at TEXT,last_error TEXT)`
    ];
    for(const sql of statements)await env.MEMBERS_DB.prepare(sql).run();
    for(const [key,segment] of Object.entries(segmentDefinitions)){
      await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_segments (id,segment_key,label,minimum_tier,marketing,active,rules_json,updated_at,created_at) VALUES (?,?,?,?,?,1,?,?,?)`).bind(segment.id,key,segment.label,segment.minimumTier,segment.marketing?1:0,JSON.stringify(segment),iso(env),iso(env)).run();
    }
    return true;
  })().catch(error=>{schemaPromise=null;throw error});
  return schemaPromise;
}

async function memberByEmail(env,email){return first(env.MEMBERS_DB.prepare(`SELECT id,email,display_name,role,tier,status,marketing_status,source,email_verified_at,created_at,updated_at,last_login_at FROM members WHERE email=? AND status<>'deleted' LIMIT 1`).bind(email))}
async function memberById(env,memberId){return first(env.MEMBERS_DB.prepare(`SELECT id,email,display_name,role,tier,status,marketing_status,source,email_verified_at,created_at,updated_at,last_login_at FROM members WHERE id=? AND status<>'deleted' LIMIT 1`).bind(memberId))}
async function preferences(env,memberId){return first(env.MEMBERS_DB.prepare('SELECT * FROM email_preferences WHERE member_id=? LIMIT 1').bind(memberId))}
function preferenceInput(input,current={}){return{
  public_daily_brief:bool(input.public_daily_brief??input.daily,current.public_daily_brief===1)?1:0,
  public_weekly_digest:bool(input.public_weekly_digest??input.weekly,current.public_weekly_digest!==0)?1:0,
  release_notices:bool(input.release_notices,current.release_notices!==0)?1:0,
  supporter_weekly_member_brief:bool(input.supporter_weekly_member_brief,current.supporter_weekly_member_brief!==0)?1:0,
  intelligence_daily_member_brief:bool(input.intelligence_daily_member_brief,current.intelligence_daily_member_brief!==0)?1:0,
  research_pro_reports:bool(input.research_pro_reports,current.research_pro_reports!==0)?1:0,
  locale:clean(input.locale||current.locale||'en',20),timezone:clean(input.timezone||current.timezone||'Europe/Paris',80),
  digest_day:input.digest_day===''||input.digest_day===undefined?(current.digest_day??null):Math.max(0,Math.min(6,Number(input.digest_day))),
  digest_hour:input.digest_hour===''||input.digest_hour===undefined?(current.digest_hour??null):Math.max(0,Math.min(23,Number(input.digest_hour)))
}}
async function savePreferences(env,memberId,input){const current=await preferences(env,memberId)||{};const p=preferenceInput(input,current);const stamp=iso(env);await env.MEMBERS_DB.prepare(`INSERT INTO email_preferences (member_id,public_daily_brief,public_weekly_digest,release_notices,supporter_weekly_member_brief,intelligence_daily_member_brief,research_pro_reports,locale,timezone,digest_day,digest_hour,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(member_id) DO UPDATE SET public_daily_brief=excluded.public_daily_brief,public_weekly_digest=excluded.public_weekly_digest,release_notices=excluded.release_notices,supporter_weekly_member_brief=excluded.supporter_weekly_member_brief,intelligence_daily_member_brief=excluded.intelligence_daily_member_brief,research_pro_reports=excluded.research_pro_reports,locale=excluded.locale,timezone=excluded.timezone,digest_day=excluded.digest_day,digest_hour=excluded.digest_hour,updated_at=excluded.updated_at`).bind(memberId,p.public_daily_brief,p.public_weekly_digest,p.release_notices,p.supporter_weekly_member_brief,p.intelligence_daily_member_brief,p.research_pro_reports,p.locale,p.timezone,p.digest_day,p.digest_hour,stamp,stamp).run();return p}
async function issueToken(env,memberId,purpose,scope={},minutes=30){const raw=tokenValue(env,purpose);const tokenHash=await hash(raw);const stamp=iso(env);await env.MEMBERS_DB.prepare('UPDATE email_action_tokens SET revoked_at=? WHERE member_id=? AND purpose=? AND used_at IS NULL AND revoked_at IS NULL').bind(stamp,memberId,purpose).run();await env.MEMBERS_DB.prepare('INSERT INTO email_action_tokens (id,member_id,token_hash,purpose,scope_json,expires_at,created_at) VALUES (?,?,?,?,?,?,?)').bind(id(env,'email-token'),memberId,tokenHash,purpose,JSON.stringify(scope),iso(env,minutes*60*1000),stamp).run();return raw}
async function tokenRecord(env,raw,purpose){if(!raw)return null;return first(env.MEMBERS_DB.prepare('SELECT * FROM email_action_tokens WHERE token_hash=? AND purpose=? LIMIT 1').bind(await hash(raw),purpose))}
async function validToken(env,raw,purpose,{reusable=false}={}){const record=await tokenRecord(env,raw,purpose);if(!record||record.revoked_at||(!reusable&&record.used_at)||String(record.expires_at||'')<=iso(env))return null;return record}
async function markTokenUsed(env,record){await env.MEMBERS_DB.prepare('UPDATE email_action_tokens SET used_at=? WHERE id=? AND used_at IS NULL').bind(iso(env),record.id).run()}
async function appendConsent(env,memberId,granted,sourcePage,wordingVersion='email-consent-v2'){const stamp=iso(env);const consentId=id(env,'email-consent');await env.MEMBERS_DB.prepare(`INSERT INTO email_consents (id,member_id,consent_type,granted,wording_version,source_page,granted_at,withdrawn_at,created_at) VALUES (?,?,'marketing_email',?,?,?,?,?,?)`).bind(consentId,memberId,granted?1:0,wordingVersion,sourcePage,granted?stamp:null,granted?null:stamp,stamp).run();return consentId}
async function emailHash(email){return hash(String(email||'').trim().toLowerCase())}
async function activeSuppression(env,memberId){return first(env.MEMBERS_DB.prepare(`SELECT id,reason FROM email_suppressions WHERE member_id=? AND active=1 AND scope='all_marketing' LIMIT 1`).bind(memberId))}
async function suppress(env,member,reason='unsubscribe',source='subscriber-action'){const stamp=iso(env);const existing=await activeSuppression(env,member.id);if(existing){await env.MEMBERS_DB.prepare('UPDATE email_suppressions SET reason=?,source=?,updated_at=? WHERE id=?').bind(reason,source,stamp,existing.id).run();return existing.id}const suppressionId=id(env,'email-suppression');await env.MEMBERS_DB.prepare(`INSERT INTO email_suppressions (id,member_id,recipient_email_hash,scope,reason,source,active,suppressed_at,updated_at) VALUES (?,?,?,'all_marketing',?,?,1,?,?)`).bind(suppressionId,member.id,await emailHash(member.email),reason,source,stamp,stamp).run();return suppressionId}
async function clearSuppressions(env,memberId,consentId){await env.MEMBERS_DB.prepare(`UPDATE email_suppressions SET active=0,cleared_at=?,cleared_by_consent_id=?,updated_at=? WHERE member_id=? AND active=1`).bind(iso(env),consentId,iso(env),memberId).run()}

async function syncSegments(env,member){const p=await preferences(env,member.id)||await savePreferences(env,member.id,{});const suppressed=Boolean(await activeSuppression(env,member.id));const eligible=member.status==='active'&&member.marketing_status==='subscribed'&&Boolean(member.email_verified_at)&&!suppressed;const stamp=iso(env);for(const [key,definition] of Object.entries(segmentDefinitions)){
    let state='removed';let reason='preference-disabled';
    if(key==='transactional_account'){state=member.status==='active'?'active':'eligible';reason='account-lifecycle'}
    else if(key==='suppressed_do_not_send'){state=suppressed?'active':'removed';reason=suppressed?'active-suppression':'not-suppressed'}
    else if(eligible&&tierAtLeast(member.tier,definition.minimumTier)&&p[definition.preference]===1){state='active';reason='verified-consent-preference-tier'}
    else if(suppressed){state='suppressed';reason='active-suppression'}
    else if(!eligible){state='paused';reason='not-currently-marketing-eligible'}
    await env.MEMBERS_DB.prepare(`INSERT INTO email_segment_memberships (segment_id,member_id,state,source,reason,eligible_at,activated_at,removed_at,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(segment_id,member_id) DO UPDATE SET state=excluded.state,source=excluded.source,reason=excluded.reason,eligible_at=excluded.eligible_at,activated_at=excluded.activated_at,removed_at=excluded.removed_at,updated_at=excluded.updated_at`).bind(definition.id,member.id,state,'phase4-email-lifecycle',reason,state==='eligible'||state==='active'?stamp:null,state==='active'?stamp:null,state==='removed'?stamp:null,stamp,stamp).run();
  }
}

async function syncBrevoContact(env,member,{blacklisted=false}={}){const stamp=iso(env);const localStateHash=await hash(JSON.stringify({email:member.email,name:member.display_name,tier:member.tier,status:member.marketing_status,blacklisted}));if(!providerConfigured(env)){await env.MEMBERS_DB.prepare(`INSERT INTO email_provider_contacts (member_id,provider,sync_status,local_state_hash,last_checked_at,last_error,updated_at,created_at) VALUES (?,'brevo','retry',?,?,?, ?,?) ON CONFLICT(member_id,provider) DO UPDATE SET sync_status='retry',local_state_hash=excluded.local_state_hash,last_checked_at=excluded.last_checked_at,last_error=excluded.last_error,updated_at=excluded.updated_at`).bind(member.id,localStateHash,stamp,'Brevo is not configured',stamp,stamp).run();return{configured:false,synced:false,error:'Brevo is not configured'}}
  const payload={email:member.email,attributes:{FIRSTNAME:member.display_name||'',MATRIX_TIER:member.tier||'free',MATRIX_STATUS:member.marketing_status||'pending'},emailBlacklisted:Boolean(blacklisted),updateEnabled:true};
  try{const response=await providerFetch(env)('https://api.brevo.com/v3/contacts',{method:'POST',headers:{accept:'application/json','content-type':'application/json','api-key':String(env.BREVO_API_KEY)},body:JSON.stringify(payload)});const text=await response.text();let data={};try{data=JSON.parse(text||'{}')}catch{}const success=response.status===201||response.status===204;await env.MEMBERS_DB.prepare(`INSERT INTO email_provider_contacts (member_id,provider,provider_contact_id,sync_status,provider_state_json,local_state_hash,last_synced_at,last_checked_at,last_error,updated_at,created_at) VALUES (?,'brevo',?,?,?,?,?,?,?,?,?) ON CONFLICT(member_id,provider) DO UPDATE SET provider_contact_id=COALESCE(excluded.provider_contact_id,email_provider_contacts.provider_contact_id),sync_status=excluded.sync_status,provider_state_json=excluded.provider_state_json,local_state_hash=excluded.local_state_hash,last_synced_at=excluded.last_synced_at,last_checked_at=excluded.last_checked_at,last_error=excluded.last_error,updated_at=excluded.updated_at`).bind(member.id,clean(data.id||'',120)||null,success?(blacklisted?'suppressed':'synced'):'retry',JSON.stringify({status:response.status,blacklisted}),localStateHash,success?stamp:null,stamp,success?null:clean(data.message||text||'Provider contact sync failed',500),stamp,stamp).run();return{configured:true,synced:success,status:response.status,providerContactId:data.id||null,error:success?null:clean(data.message||text,500)}}catch(error){await env.MEMBERS_DB.prepare(`INSERT INTO email_provider_contacts (member_id,provider,sync_status,local_state_hash,last_checked_at,last_error,updated_at,created_at) VALUES (?,'brevo','retry',?,?,?,?,?) ON CONFLICT(member_id,provider) DO UPDATE SET sync_status='retry',local_state_hash=excluded.local_state_hash,last_checked_at=excluded.last_checked_at,last_error=excluded.last_error,updated_at=excluded.updated_at`).bind(member.id,localStateHash,stamp,clean(error?.message,500),stamp,stamp).run();return{configured:true,synced:false,error:clean(error?.message,500)}}
}

function emailTemplate({heading,name,copy,actionLabel,actionUrl,footer='You can manage preferences or unsubscribe at any time.'}){const safeUrl=html(actionUrl);return{htmlContent:`<!doctype html><html><body style="background:#050505;color:#f3e6bd;font-family:Arial,sans-serif;padding:28px"><div style="max-width:660px;margin:auto;border:1px solid #8d7137;border-radius:18px;padding:28px;background:#0b0905"><h1 style="color:#d8b56a">${html(heading)}</h1><p>Hello ${html(name||'Reader')},</p><p>${html(copy)}</p><p><a href="${safeUrl}" style="display:inline-block;padding:14px 20px;border-radius:12px;background:#d8b56a;color:#090702;text-decoration:none;font-weight:bold">${html(actionLabel)}</a></p><p style="font-size:13px;color:#b9aa82">${html(footer)}</p></div></body></html>`,textContent:`${heading}\n\nHello ${name||'Reader'},\n\n${copy}\n\n${actionLabel}: ${actionUrl}\n\n${footer}`}}
async function enqueue(env,member,{campaignId=null,messageKind,subject,htmlContent,textContent,idempotencyKey}){const outboxId=id(env,'email-outbox');const payload={to:{email:member.email,name:member.display_name||'Reader'},subject,htmlContent,textContent};await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_outbox (id,member_id,campaign_id,message_kind,recipient_email_hash,payload_json,idempotency_key,status,available_at,updated_at,created_at) VALUES (?,?,?,?,?,?,?,'pending',?,?,?)`).bind(outboxId,member.id,campaignId,messageKind,await emailHash(member.email),JSON.stringify(payload),idempotencyKey,iso(env),iso(env),iso(env)).run();return outboxId}
async function sendProviderEmail(env,payload){if(!providerConfigured(env))return{configured:false,sent:false,error:'Brevo transactional delivery is not configured'};try{const response=await providerFetch(env)('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{accept:'application/json','content-type':'application/json','api-key':String(env.BREVO_API_KEY)},body:JSON.stringify({sender:{email:String(env.MEMBERS_FROM_EMAIL),name:String(env.MEMBERS_FROM_NAME||'Matrix Reprogrammed')},to:[payload.to],subject:payload.subject,htmlContent:payload.htmlContent,textContent:payload.textContent})});const text=await response.text();let data={};try{data=JSON.parse(text||'{}')}catch{}return{configured:true,sent:response.status===201,status:response.status,messageId:data.messageId||null,error:response.status===201?null:clean(data.message||text||'Brevo rejected email',500)}}catch(error){return{configured:true,sent:false,error:clean(error?.message,500)}}}
async function processOutbox(env,{limit=50,memberId=null}={}){await ensureSchema(env);const stamp=iso(env);const rows=memberId?await all(env.MEMBERS_DB.prepare(`SELECT * FROM email_outbox WHERE member_id=? AND status IN ('pending','retry') AND available_at<=? ORDER BY created_at LIMIT ?`).bind(memberId,stamp,limit)):await all(env.MEMBERS_DB.prepare(`SELECT * FROM email_outbox WHERE status IN ('pending','retry') AND available_at<=? ORDER BY created_at LIMIT ?`).bind(stamp,limit));let sent=0,retry=0,failed=0;for(const row of rows){await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='sending',locked_at=?,attempt_count=attempt_count+1,updated_at=? WHERE id=? AND status IN ('pending','retry')`).bind(stamp,stamp,row.id).run();let payload={};try{payload=JSON.parse(row.payload_json||'{}')}catch{}const delivery=await sendProviderEmail(env,payload);if(delivery.sent){sent+=1;await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='sent',provider_message_id=?,last_error=NULL,updated_at=? WHERE id=?`).bind(delivery.messageId,iso(env),row.id).run();if(row.campaign_id){const existing=await first(env.MEMBERS_DB.prepare('SELECT id FROM email_deliveries WHERE campaign_id=? AND member_id=? LIMIT 1').bind(row.campaign_id,row.member_id));if(existing)await env.MEMBERS_DB.prepare(`UPDATE email_deliveries SET status='sent',provider_message_id=?,sent_at=?,last_event_at=?,updated_at=? WHERE id=?`).bind(delivery.messageId,iso(env),iso(env),iso(env),existing.id).run();}}
    else{const attempts=Number(row.attempt_count||0)+1;if(attempts>=5){failed+=1;await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='failed',last_error=?,updated_at=? WHERE id=?`).bind(delivery.error||'Delivery failed',iso(env),row.id).run();if(row.campaign_id)await env.MEMBERS_DB.prepare(`UPDATE email_deliveries SET status='failed',failed_at=?,failure_reason=?,updated_at=? WHERE campaign_id=? AND member_id=?`).bind(iso(env),delivery.error||'Delivery failed',iso(env),row.campaign_id,row.member_id).run()}else{retry+=1;await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='retry',available_at=?,last_error=?,updated_at=? WHERE id=?`).bind(iso(env,Math.min(60,attempts*5)*60*1000),delivery.error||'Delivery retry queued',iso(env),row.id).run();}}
  }
  const campaignIds=[...new Set(rows.map(row=>row.campaign_id).filter(Boolean))];for(const campaignId of campaignIds)await refreshCampaign(env,campaignId);return{processed:rows.length,sent,retry,failed}}
async function refreshCampaign(env,campaignId){const counts=await first(env.MEMBERS_DB.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN status IN ('sent','delivered','opened','clicked') THEN 1 ELSE 0 END) sent,SUM(CASE WHEN status IN ('failed','hard_bounce','complaint') THEN 1 ELSE 0 END) failed,SUM(CASE WHEN status IN ('queued','deferred') THEN 1 ELSE 0 END) pending FROM email_deliveries WHERE campaign_id=?`).bind(campaignId));const total=Number(counts?.total||0),sent=Number(counts?.sent||0),failed=Number(counts?.failed||0),pending=Number(counts?.pending||0);const status=pending?'sending':failed&&sent?'partially_failed':failed&&!sent?'failed':'sent';await env.MEMBERS_DB.prepare('UPDATE email_campaigns SET status=?,recipient_count=?,sent_count=?,failed_count=?,completed_at=?,updated_at=? WHERE id=?').bind(status,total,sent,failed,pending?null:iso(env),iso(env),campaignId).run()}

async function upsertSignupMember(env,input,{resubscribe=false}={}){const email=clean(input.email,254).toLowerCase();const name=clean(input.name,120);const stamp=iso(env);const requestedId='subscriber-'+(await hash(email)).slice(0,24);await env.MEMBERS_DB.prepare(`INSERT INTO members (id,email,display_name,role,tier,status,marketing_status,source,created_at,updated_at) VALUES (?,?,?,'member','free','pending','pending',?,?,?) ON CONFLICT(email) DO UPDATE SET display_name=CASE WHEN excluded.display_name<>'' THEN excluded.display_name ELSE members.display_name END,status=CASE WHEN members.status='deleted' THEN members.status ELSE members.status END,marketing_status=CASE WHEN ?=1 THEN 'pending' WHEN members.marketing_status IN ('suppressed','bounced','complained') THEN members.marketing_status ELSE 'pending' END,source=excluded.source,updated_at=excluded.updated_at`).bind(requestedId,email,name,clean(input.source||input.path||'newsletter-signup',180),stamp,stamp,resubscribe?1:0).run();return memberByEmail(env,email)}
async function verificationRateLimited(env,memberId){const since=iso(env,-60*60*1000);const row=await first(env.MEMBERS_DB.prepare(`SELECT COUNT(*) count FROM email_action_tokens WHERE member_id=? AND purpose IN ('verify_marketing','resubscribe') AND created_at>=?`).bind(memberId,since));return Number(row?.count||0)>=5}

async function handleSignup(request,env,{resubscribe=false}={}){await ensureSchema(env);const input=await body(request);if(clean(input.website,200))return json({ok:false,error:'Spam trap triggered'},400);const email=clean(input.email,254).toLowerCase();if(!validEmail(email))return json({ok:false,error:'Valid email required'},400);if(!bool(input.consent,false))return json({ok:false,error:'Explicit email consent is required'},400);let member=await upsertSignupMember(env,{...input,email},{resubscribe});if(!member)return json({ok:false,saved:false,error:'Subscriber record could not be read after write'},503);if(await verificationRateLimited(env,member.id))return json({ok:false,saved:true,error:'Too many verification requests. Try again later.'},429);const sourcePage=clean(input.path||input.sourcePage||input.source||'newsletter-signup',240);const consentId=await appendConsent(env,member.id,true,sourcePage,resubscribe?'email-resubscribe-v1':'email-signup-v2');await savePreferences(env,member.id,input);const purpose=resubscribe?'resubscribe':'verify_marketing';const rawToken=await issueToken(env,member.id,purpose,{consentId,sourcePage},30);member=await memberById(env,member.id);await syncSegments(env,member);const providerSync=await syncBrevoContact(env,member,{blacklisted:false});const verifyUrl=`${origin(request)}/api/email/verify?purpose=${encodeURIComponent(purpose)}&token=${encodeURIComponent(rawToken)}`;const template=emailTemplate({heading:resubscribe?'Confirm your resubscription':'Verify your email',name:member.display_name,copy:resubscribe?'Confirm that you want to rejoin Matrix Reprogrammed email briefings.':'Confirm your address to activate the briefings you selected.',actionLabel:resubscribe?'Confirm resubscription':'Verify email',actionUrl:verifyUrl,footer:'This one-time link expires in 30 minutes. If you did not request it, ignore this email.'});await enqueue(env,member,{messageKind:purpose,subject:resubscribe?'Confirm your Matrix Reprogrammed resubscription':'Verify your Matrix Reprogrammed email',...template,idempotencyKey:`${purpose}:${member.id}:${await hash(rawToken)}`});const delivery=await processOutbox(env,{memberId:member.id,limit:5});await audit(env,member.id,resubscribe?'email.resubscribe.requested':'email.signup','member',member.id,{sourcePage,providerSynced:providerSync.synced,verificationSent:delivery.sent>0});return json({ok:true,accepted:true,saved:true,status:'pending_verification',providerSync,verification:{queued:true,sent:delivery.sent>0,retryQueued:delivery.retry>0},message:delivery.sent?'Check your email to verify the subscription.':'Your subscriber record is saved. Verification delivery is queued and will retry when email delivery is available.',...(testMode(env)?{testVerificationToken:rawToken}: {})},202)}

async function handleVerify(request,env){await ensureSchema(env);const url=new URL(request.url);const purpose=clean(url.searchParams.get('purpose')||'verify_marketing',40);if(!['verify_marketing','resubscribe'].includes(purpose))return json({ok:false,error:'Invalid verification purpose'},400);const raw=clean(url.searchParams.get('token'),400);const record=await validToken(env,raw,purpose);const failure=reason=>testMode(env)?json({ok:false,error:reason},400):redirect(`${origin(request)}/email-status.html?error=${encodeURIComponent(reason)}`);if(!record)return failure('expired-or-used');let member=await memberById(env,record.member_id);if(!member)return failure('member-not-found');let scope={};try{scope=JSON.parse(record.scope_json||'{}')}catch{}const stamp=iso(env);await env.MEMBERS_DB.prepare(`UPDATE members SET status='active',marketing_status='subscribed',email_verified_at=COALESCE(email_verified_at,?),updated_at=? WHERE id=?`).bind(stamp,stamp,member.id).run();await markTokenUsed(env,record);if(purpose==='resubscribe')await clearSuppressions(env,member.id,scope.consentId||null);member=await memberById(env,member.id);await savePreferences(env,member.id,{});await syncSegments(env,member);const preferenceToken=await issueToken(env,member.id,'preferences',{memberId:member.id},365*24*60);const unsubscribeToken=await issueToken(env,member.id,'unsubscribe',{memberId:member.id},365*24*60);const providerSync=await syncBrevoContact(env,member,{blacklisted:false});const dashboardUrl=`${origin(request)}/subscriber-dashboard.html?token=${encodeURIComponent(preferenceToken)}`;const unsubscribeUrl=`${origin(request)}/api/email/unsubscribe?token=${encodeURIComponent(unsubscribeToken)}`;const template=emailTemplate({heading:'Welcome to Matrix Reprogrammed',name:member.display_name,copy:'Your verified email preferences are active. Use the dashboard to control daily, weekly and release notices.',actionLabel:'Open subscriber dashboard',actionUrl:dashboardUrl,footer:`Unsubscribe: ${unsubscribeUrl}`});await enqueue(env,member,{messageKind:'welcome',subject:'Welcome to Matrix Reprogrammed',...template,idempotencyKey:`welcome:${member.id}:${stamp.slice(0,10)}`});const delivery=await processOutbox(env,{memberId:member.id,limit:5});await audit(env,member.id,'email.verified','member',member.id,{purpose,providerSynced:providerSync.synced,welcomeSent:delivery.sent>0});if(testMode(env))return json({ok:true,verified:true,memberId:member.id,preferenceToken,unsubscribeToken,dashboardUrl,providerSync,welcomeSent:delivery.sent>0});return redirect(`${origin(request)}/email-status.html?verified=1&token=${encodeURIComponent(preferenceToken)}`)}

async function preferenceContext(env,raw){const token=await validToken(env,raw,'preferences',{reusable:true});if(!token)return null;const member=await memberById(env,token.member_id);if(!member)return null;const p=await preferences(env,member.id)||await savePreferences(env,member.id,{});const segments=await all(env.MEMBERS_DB.prepare(`SELECT s.segment_key,m.state,m.reason FROM email_segment_memberships m JOIN email_segments s ON s.id=m.segment_id WHERE m.member_id=? ORDER BY s.segment_key`).bind(member.id));return{token,member,preferences:p,segments,suppressed:Boolean(await activeSuppression(env,member.id))}}
async function handlePreferences(request,env){await ensureSchema(env);const url=new URL(request.url);const input=request.method==='POST'?await body(request):{};const raw=clean(input.token||url.searchParams.get('token'),400);const context=await preferenceContext(env,raw);if(!context)return json({ok:false,error:'Invalid or expired preferences token'},401);if(request.method==='GET')return json({ok:true,subscriber:{email:context.member.email,displayName:context.member.display_name,status:context.member.status,marketingStatus:context.member.marketing_status,tier:context.member.tier,verifiedAt:context.member.email_verified_at},preferences:context.preferences,segments:context.segments,suppressed:context.suppressed});const p=await savePreferences(env,context.member.id,input);const member=await memberById(env,context.member.id);await syncSegments(env,member);await audit(env,member.id,'email.preferences.updated','member',member.id,{preferences:p});return json({ok:true,saved:true,preferences:p,segments:await all(env.MEMBERS_DB.prepare(`SELECT s.segment_key,m.state,m.reason FROM email_segment_memberships m JOIN email_segments s ON s.id=m.segment_id WHERE m.member_id=? ORDER BY s.segment_key`).bind(member.id))})}
async function handleSubscriber(request,env){if(request.method!=='GET')return json({ok:false,error:'Method not allowed'},405);return handlePreferences(request,env)}

async function unsubscribeMember(env,member,source='unsubscribe-link'){const consentId=await appendConsent(env,member.id,false,source,'email-unsubscribe-v1');await env.MEMBERS_DB.prepare(`UPDATE members SET marketing_status='unsubscribed',updated_at=? WHERE id=?`).bind(iso(env),member.id).run();await suppress(env,member,'unsubscribe',source);const updated=await memberById(env,member.id);await syncSegments(env,updated);const providerSync=await syncBrevoContact(env,updated,{blacklisted:true});await audit(env,member.id,'email.unsubscribed','member',member.id,{source,consentId,providerSynced:providerSync.synced});return providerSync}
async function handleUnsubscribe(request,env){await ensureSchema(env);const url=new URL(request.url);const input=request.method==='POST'?await body(request):{};const raw=clean(input.token||url.searchParams.get('token'),400);const record=await validToken(env,raw,'unsubscribe',{reusable:true});if(!record)return testMode(env)?json({ok:false,error:'Invalid or expired unsubscribe token'},400):redirect(`${origin(request)}/email-status.html?error=invalid-unsubscribe-link`);const member=await memberById(env,record.member_id);if(!member)return json({ok:false,error:'Subscriber not found'},404);const providerSync=await unsubscribeMember(env,member,'unsubscribe-link');if(testMode(env)||request.method==='POST')return json({ok:true,unsubscribed:true,providerSync});return redirect(`${origin(request)}/email-status.html?unsubscribed=1`)}
async function handleResubscribe(request,env){if(request.method!=='POST')return json({ok:false,error:'Method not allowed'},405);return handleSignup(request,env,{resubscribe:true})}

function eventType(value){const raw=String(value||'').toLowerCase().replace(/[ _-]+/g,'_');const map={delivered:'delivered',request:'sent',sent:'sent',opened:'opened',unique_opened:'opened',click:'clicked',clicked:'clicked',soft_bounce:'soft_bounce',hard_bounce:'hard_bounce',blocked:'hard_bounce',spam:'complaint',complaint:'complaint',unsubscribed:'unsubscribed',error:'failed',deferred:'deferred'};return map[raw]||raw||'unknown'}
async function handleWebhook(request,env){await ensureSchema(env);const secret=request.headers.get('x-email-webhook-secret')||new URL(request.url).searchParams.get('secret')||'';if(!env?.EMAIL_WEBHOOK_SECRET||!secureEqual(secret,env.EMAIL_WEBHOOK_SECRET))return json({ok:false,error:'Invalid webhook secret'},403);const raw=await request.text();const payloadHash=await hash(raw);const requestId=clean(request.headers.get('x-brevo-request-id')||request.headers.get('x-request-id')||payloadHash,200);const existing=await first(env.MEMBERS_DB.prepare(`SELECT id FROM email_webhook_receipts WHERE provider='brevo' AND request_id=? LIMIT 1`).bind(requestId));if(existing)return json({ok:true,duplicate:true,processed:0});let parsed;try{parsed=JSON.parse(raw||'{}')}catch{return json({ok:false,error:'Invalid webhook JSON'},400)}const events=Array.isArray(parsed)?parsed:[parsed];const receiptId=id(env,'email-webhook');await env.MEMBERS_DB.prepare(`INSERT INTO email_webhook_receipts (id,provider,request_id,signature_valid,payload_hash,event_count,processing_status,received_at) VALUES (?,'brevo',?,1,?,?,'received',?)`).bind(receiptId,requestId,payloadHash,events.length,iso(env)).run();let processed=0,duplicates=0,suppressions=0;for(const item of events){const providerMessageId=clean(item['message-id']||item.messageId||item.message_id,240);const type=eventType(item.event||item.type);const email=clean(item.email,254).toLowerCase();const providerEventId=clean(item.event_id||item.id||await hash(JSON.stringify({providerMessageId,type,email,date:item.date||item.ts_event||item.timestamp||''})),240);const duplicate=await first(env.MEMBERS_DB.prepare(`SELECT id FROM email_events WHERE provider='brevo' AND provider_event_id=? LIMIT 1`).bind(providerEventId));if(duplicate){duplicates+=1;continue}let outbox=providerMessageId?await first(env.MEMBERS_DB.prepare('SELECT * FROM email_outbox WHERE provider_message_id=? LIMIT 1').bind(providerMessageId)):null;let member=outbox?await memberById(env,outbox.member_id):(email?await memberByEmail(env,email):null);const campaignId=outbox?.campaign_id||clean(item.campaign_id||item.campaignId,160)||null;await env.MEMBERS_DB.prepare(`INSERT INTO email_events (id,provider,provider_event_id,provider_message_id,campaign_id,member_id,event_type,event_at,payload_hash,payload_json,processed_at,processing_status,created_at) VALUES (?,'brevo',?,?,?,?,?,?,?,?,?,'processed',?)`).bind(id(env,'email-event'),providerEventId,providerMessageId||null,campaignId,member?.id||null,type,clean(item.date||item.ts_event||item.timestamp||iso(env),80),await hash(JSON.stringify(item)),JSON.stringify(item),iso(env),iso(env)).run();if(outbox?.campaign_id){const updates={delivered:['delivered',iso(env)],opened:['opened',iso(env)],clicked:['clicked',iso(env)],soft_bounce:['soft_bounce',iso(env)],hard_bounce:['hard_bounce',iso(env)],complaint:['complaint',iso(env)],unsubscribed:['unsubscribed',iso(env)],failed:['failed',iso(env)],deferred:['deferred',iso(env)]};const pair=updates[type];if(pair){const columns={delivered:'delivered_at',opened:'opened_at',clicked:'clicked_at',soft_bounce:'failed_at',hard_bounce:'failed_at',complaint:'failed_at',unsubscribed:'failed_at',failed:'failed_at',deferred:'last_event_at'};await env.MEMBERS_DB.prepare(`UPDATE email_deliveries SET status=?,${columns[type]}=?,last_event_at=?,failure_reason=?,updated_at=? WHERE campaign_id=? AND member_id=?`).bind(pair[0],pair[1],iso(env),['soft_bounce','hard_bounce','complaint','failed'].includes(type)?type:null,iso(env),outbox.campaign_id,outbox.member_id).run();await refreshCampaign(env,outbox.campaign_id)}}if(member&&['hard_bounce','complaint','unsubscribed'].includes(type)){const status=type==='hard_bounce'?'bounced':type==='complaint'?'complained':'unsubscribed';await env.MEMBERS_DB.prepare('UPDATE members SET marketing_status=?,updated_at=? WHERE id=?').bind(status,iso(env),member.id).run();await suppress(env,member,type,'brevo-webhook');member=await memberById(env,member.id);await syncSegments(env,member);suppressions+=1}processed+=1}
  await env.MEMBERS_DB.prepare(`UPDATE email_webhook_receipts SET processing_status='processed',processed_at=? WHERE id=?`).bind(iso(env),receiptId).run();return json({ok:true,processed,duplicates,suppressions})}

async function eligibleMembers(env,segmentKey){const definition=segmentDefinitions[segmentKey];if(!definition)return[];return all(env.MEMBERS_DB.prepare(`SELECT m.id,m.email,m.display_name,m.role,m.tier,m.status,m.marketing_status,m.email_verified_at FROM email_segment_memberships esm JOIN members m ON m.id=esm.member_id WHERE esm.segment_id=? AND esm.state='active' AND m.status='active' AND m.marketing_status='subscribed' AND m.email_verified_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM email_suppressions s WHERE s.member_id=m.id AND s.active=1 AND s.scope='all_marketing') ORDER BY m.id`).bind(definition.id))}
async function createCampaign(env,input,actor='admin'){const kind=clean(input.kind||'daily',20);if(!['daily','weekly','release','monthly','test'].includes(kind))throw new Error('Unsupported campaign kind');const segmentKey=clean(input.segmentKey||input.segment_key||(kind==='weekly'?'public_weekly_digest':'public_daily_brief'),80);const definition=segmentDefinitions[segmentKey];if(!definition||!definition.marketing)throw new Error('Unknown marketing segment');const subject=clean(input.subject||`${kind==='weekly'?'Weekly Signal Drop':'Daily Control Brief'} — ${iso(env).slice(0,10)}`,180);const htmlContent=String(input.htmlContent||input.html_content||'').slice(0,250000);const textContent=String(input.textContent||input.text_content||'').slice(0,150000);if(subject.length<4||htmlContent.length<20||textContent.length<10)throw new Error('Campaign subject, HTML and text content are required');const contentHash=await hash(JSON.stringify({subject,htmlContent,textContent,segmentKey}));let content=await first(env.MEMBERS_DB.prepare('SELECT id FROM email_campaign_content_versions WHERE content_hash=? LIMIT 1').bind(contentHash));if(!content){content={id:id(env,'email-content')};await env.MEMBERS_DB.prepare(`INSERT INTO email_campaign_content_versions (id,campaign_kind,subject,preheader,html_content,text_content,canonical_record_ids_json,content_hash,evidence_checkpoint_at,fact_speculation_boundary_verified,reviewed_by,reviewed_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,1,?,?,?)`).bind(content.id,kind,subject,clean(input.preheader,180),htmlContent,textContent,JSON.stringify(Array.isArray(input.canonicalRecordIds)?input.canonicalRecordIds:[]),contentHash,clean(input.evidenceCheckpointAt||iso(env),80),actor,iso(env),iso(env)).run()}const campaignKey=clean(input.campaignKey||`${kind}:${segmentKey}:${iso(env).slice(0,10)}`,180);let campaign=await first(env.MEMBERS_DB.prepare('SELECT * FROM email_campaigns WHERE campaign_key=? LIMIT 1').bind(campaignKey));if(!campaign){const campaignId=id(env,'email-campaign');const status=input.scheduledAt?'scheduled':'review';await env.MEMBERS_DB.prepare(`INSERT INTO email_campaigns (id,campaign_key,kind,segment_id,content_version_id,status,scheduled_at,updated_at,created_at) VALUES (?,?,?,?,?,?,?,?,?)`).bind(campaignId,campaignKey,kind,definition.id,content.id,status,input.scheduledAt||null,iso(env),iso(env)).run();campaign=await first(env.MEMBERS_DB.prepare('SELECT * FROM email_campaigns WHERE id=?').bind(campaignId))}return campaign}
async function queueCampaign(env,campaign){const content=await first(env.MEMBERS_DB.prepare('SELECT * FROM email_campaign_content_versions WHERE id=?').bind(campaign.content_version_id));const segment=await first(env.MEMBERS_DB.prepare('SELECT segment_key FROM email_segments WHERE id=?').bind(campaign.segment_id));const recipients=await eligibleMembers(env,segment.segment_key);for(const member of recipients){await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_deliveries (id,campaign_id,member_id,recipient_email_hash,status,queued_at,updated_at) VALUES (?,?,?,?, 'queued',?,?)`).bind(id(env,'email-delivery'),campaign.id,member.id,await emailHash(member.email),iso(env),iso(env)).run();await enqueue(env,member,{campaignId:campaign.id,messageKind:campaign.kind,subject:content.subject,htmlContent:content.html_content,textContent:content.text_content,idempotencyKey:`${campaign.id}:${member.id}`})}await env.MEMBERS_DB.prepare(`UPDATE email_campaigns SET status='sending',started_at=COALESCE(started_at,?),recipient_count=?,updated_at=? WHERE id=?`).bind(iso(env),recipients.length,iso(env),campaign.id).run();return{recipientCount:recipients.length}}
async function loadCampaignSource(request,env,kind){if(!env?.ASSETS||typeof env.ASSETS.fetch!=='function')return null;const candidates=kind==='weekly'?['/downloads/weekly-investigation-report.json','/data/weekly-intelligence.json','/downloads/outcome-briefings.json']:['/downloads/daily-brain-brief.json','/data/live-intel.json','/downloads/outcome-briefings.json'];for(const pathname of candidates){try{const response=await env.ASSETS.fetch(new Request(new URL(pathname,request.url)));if(response.ok)return{pathname,data:await response.json()}}catch{}}return null}
function sourceItems(source){const data=source?.data;if(!data)return[];const candidates=[data.records,data.items,data.briefings,data.findings,data.entries,data.results,data.cards];for(const value of candidates)if(Array.isArray(value))return value.slice(0,8);return[]}
async function automatedCampaign(request,env,kind){if(!automationEnabled(env))return{enabled:false,created:false,reason:'EMAIL_AUTOMATION_ENABLED is not true'};const source=await loadCampaignSource(request,env,kind);const items=sourceItems(source);const title=kind==='weekly'?'Weekly Signal Drop':'Daily Control Brief';const date=iso(env).slice(0,10);const rows=items.length?items.map((item,index)=>{const heading=clean(item.title||item.headline||item.subject||item.label||`Signal ${index+1}`,180);const summary=clean(item.summary||item.description||item.body||item.finding||'',600);return{heading,summary}}):[{heading:'Evidence and intelligence update',summary:'The automated source bundle was unavailable, so no unverified claims were inserted. Open the live intelligence desk for the latest evidence-bounded records.'}];const htmlContent=`<!doctype html><html><body><h1>${html(title)} — ${date}</h1>${rows.map(row=>`<h2>${html(row.heading)}</h2><p>${html(row.summary)}</p>`).join('')}<p><strong>Evidence boundary:</strong> Records and analysis remain subject to their source and interpretive labels. Association is not proof.</p><p><a href="${origin(request)}/live-intel.html">Open Live Intel</a></p></body></html>`;const textContent=`${title} — ${date}\n\n${rows.map(row=>`${row.heading}\n${row.summary}`).join('\n\n')}\n\nEvidence boundary: association is not proof.\n${origin(request)}/live-intel.html`;const campaign=await createCampaign(env,{kind,segmentKey:kind==='weekly'?'public_weekly_digest':'public_daily_brief',subject:`${title} — ${date}`,htmlContent,textContent,campaignKey:`automation:${kind}:${date}`,canonicalRecordIds:items.map(item=>item.canonicalId||item.id).filter(Boolean),evidenceCheckpointAt:clean(source?.data?.generatedAt||iso(env),80)},'email-automation');const queued=await queueCampaign(env,campaign);const delivery=await processOutbox(env,{limit:100});await audit(env,'email-automation','email.campaign.automated','email_campaign',campaign.id,{kind,source:source?.pathname||null,...queued,...delivery});return{enabled:true,created:true,campaignId:campaign.id,source:source?.pathname||null,...queued,...delivery}}

async function adminHealth(env){await ensureSchema(env);const memberCounts=await all(env.MEMBERS_DB.prepare(`SELECT status,marketing_status,COUNT(*) count FROM members WHERE status<>'deleted' GROUP BY status,marketing_status ORDER BY status,marketing_status`));const outbox=await all(env.MEMBERS_DB.prepare(`SELECT status,COUNT(*) count FROM email_outbox GROUP BY status ORDER BY status`));const campaigns=await all(env.MEMBERS_DB.prepare(`SELECT status,COUNT(*) count FROM email_campaigns GROUP BY status ORDER BY status`));const events=await all(env.MEMBERS_DB.prepare(`SELECT event_type,COUNT(*) count FROM email_events GROUP BY event_type ORDER BY event_type`));const provider=await all(env.MEMBERS_DB.prepare(`SELECT sync_status,COUNT(*) count FROM email_provider_contacts GROUP BY sync_status ORDER BY sync_status`));return{ok:true,d1Connected:true,schemaReady:true,brevoConfigured:providerConfigured(env),automationEnabled:automationEnabled(env),memberCounts,outbox,campaigns,events,provider,requiredSecrets:{brevoApiKey:Boolean(env?.BREVO_API_KEY),fromEmail:Boolean(env?.MEMBERS_FROM_EMAIL),webhookSecret:Boolean(env?.EMAIL_WEBHOOK_SECRET),adminToken:Boolean(env?.ADMIN_API_TOKEN)}}}
async function handleAdminHealth(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);return json(await adminHealth(env))}
async function handleAdminCampaigns(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);await ensureSchema(env);if(request.method==='GET'){const campaigns=await all(env.MEMBERS_DB.prepare(`SELECT c.*,s.segment_key,v.subject,v.content_hash,(SELECT COUNT(*) FROM email_deliveries d WHERE d.campaign_id=c.id) delivery_count,(SELECT COUNT(*) FROM email_deliveries d WHERE d.campaign_id=c.id AND d.status IN ('delivered','opened','clicked')) delivered_count,(SELECT COUNT(*) FROM email_deliveries d WHERE d.campaign_id=c.id AND d.status IN ('hard_bounce','complaint','failed')) failed_delivery_count FROM email_campaigns c LEFT JOIN email_segments s ON s.id=c.segment_id JOIN email_campaign_content_versions v ON v.id=c.content_version_id ORDER BY c.created_at DESC LIMIT 100`));return json({ok:true,count:campaigns.length,campaigns})}const input=await body(request);try{const campaign=await createCampaign(env,input,'admin');let queued={recipientCount:0},delivery={processed:0,sent:0,retry:0,failed:0};if(bool(input.sendNow,false)){queued=await queueCampaign(env,campaign);delivery=await processOutbox(env,{limit:Number(input.limit||100)})}await audit(env,'admin','email.campaign.created','email_campaign',campaign.id,{sendNow:bool(input.sendNow,false),...queued,...delivery});return json({ok:true,campaign,queued,delivery},201)}catch(error){return json({ok:false,error:clean(error?.message,500)},400)}}
async function handleAdminProcess(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);const input=await body(request);return json({ok:true,...await processOutbox(env,{limit:Math.max(1,Math.min(500,Number(input.limit||100)))})})}
async function handleAdminAutomation(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);const input=await body(request);const kind=clean(input.kind||'daily',20);if(!['daily','weekly'].includes(kind))return json({ok:false,error:'Kind must be daily or weekly'},400);return json({ok:true,result:await automatedCampaign(request,env,kind)})}

async function fetchHandler(request,env,ctx){try{const path=new URL(request.url).pathname.replace(/\/+$/,'')||'/';if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{...securityHeaders,'Access-Control-Allow-Origin':origin(request),'Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,X-Admin-Token,X-Email-Webhook-Secret'}});if(!emailRoutes.has(path))return json({ok:false,error:'Unknown email lifecycle route'},404);if(!hasD1(env))return json({ok:false,configured:false,error:'MEMBERS_DB is unavailable'},503);if(request.method==='POST'&&['/newsletter-signup','/subscribe-newsletter','/api/membership/signup'].includes(path))return handleSignup(request,env);if(request.method==='GET'&&path==='/api/email/verify')return handleVerify(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/preferences')return handlePreferences(request,env);if(request.method==='GET'&&path==='/api/email/subscriber')return handleSubscriber(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/unsubscribe')return handleUnsubscribe(request,env);if(request.method==='POST'&&path==='/api/email/resubscribe')return handleResubscribe(request,env);if(request.method==='POST'&&path==='/api/email/provider-webhook')return handleWebhook(request,env);if(request.method==='GET'&&path==='/api/email/admin/health')return handleAdminHealth(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/admin/campaigns')return handleAdminCampaigns(request,env);if(request.method==='POST'&&path==='/api/email/admin/process-outbox')return handleAdminProcess(request,env);if(request.method==='POST'&&path==='/api/email/admin/run-automation')return handleAdminAutomation(request,env);return json({ok:false,error:'Method not allowed'},405)}catch(error){return json({ok:false,error:'Email lifecycle failed safely',message:clean(error?.message||error,500)},500)}}
async function scheduledHandler(event,env,ctx){if(!hasD1(env))return;const request=new Request('https://matrixreprogrammed.com/api/email/admin/run-automation');const job=async()=>{await ensureSchema(env);if(!automationEnabled(env))return;if(event?.cron==='15 7 * * 1')await automatedCampaign(request,env,'weekly');else if(event?.cron==='5 6 * * *')await automatedCampaign(request,env,'daily');await processOutbox(env,{limit:250})};if(ctx?.waitUntil)ctx.waitUntil(job());else await job()}

export {emailRoutes,ensureSchema,fetchHandler,scheduledHandler,processOutbox,automatedCampaign};
export default{fetch:fetchHandler,scheduled:scheduledHandler};
